/* VCD dumping functions */
MOD_mkTb_r16_n48 & mkTb_r16_n48_backing(tSimStateHdl simHdl)
{
  static MOD_mkTb_r16_n48 *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTb_r16_n48(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
